const items = $input.all();
const rows = items.map(i => i.json);
const dateStr = new Date().toISOString().split('T')[0];

// Group by project display_name
const grouped = {};
for (const row of rows) {
  const project = row.display_name || 'Unknown Project';
  if (!grouped[project]) {
    grouped[project] = [];
  }
  grouped[project].push(row);
}

let md = `# Weekly Market Digest - ${dateStr}\n\n`;
md += `**${rows.length} market signals across ${Object.keys(grouped).length} projects**\n\n`;

if (rows.length === 0) {
  md += '_No new market signals discovered this week._\n';
} else {
  for (const [project, signals] of Object.entries(grouped)) {
    md += `## ${project}\n\n`;
    for (const signal of signals) {
      const discoveredAt = signal.discovered_at ? new Date(signal.discovered_at).toISOString().split('T')[0] : 'unknown';
      md += `- **${signal.signal_type || 'signal'}** (${discoveredAt}): ${signal.summary || signal.title || 'No summary'}\n`;
      if (signal.source_url) {
        md += `  - Source: ${signal.source_url}\n`;
      }
      if (signal.relevance_score != null) {
        md += `  - Relevance: ${signal.relevance_score}/10\n`;
      }
    }
    md += '\n';
  }
}

return [{ json: { markdown: md, dateStr, count: rows.length } }];
